// ── Region-Based Sectioning — deterministic split by region, zero AI involvement ──
const webhookBody = $('Webhook Trigger').item.json.body;

const rows = Array.isArray(webhookBody.rows) ? webhookBody.rows : [];
const task = webhookBody.analysis_task || 'Analyse the provided data and report key findings, patterns and anomalies.';

if (rows.length === 0) {
  throw new Error('No rows found. Send { "rows": [...], "analysis_task": "..." } in the request body.');
}

const slices = { North: [], South: [], East: [], West: [] };
for (const row of rows) {
  const r = row.region || row.Region || '';
  if (slices[r] !== undefined) slices[r].push(row);
}

function rowsToText(slice, regionName) {
  if (slice.length === 0) return '[No data available for ' + regionName + ' region]';
  return slice.map((row, i) => {
    if (typeof row === 'object' && row !== null) {
      return 'Row ' + (i + 1) + ': ' + Object.entries(row).map(([k, v]) => k + '=' + v).join(', ');
    }
    return 'Row ' + (i + 1) + ': ' + row;
  }).join('\n');
}

const t1 = rowsToText(slices.North, 'North');
const t2 = rowsToText(slices.South, 'South');
const t3 = rowsToText(slices.East,  'East');
const t4 = rowsToText(slices.West,  'West');

const allRowsText = rows.map((row, i) => {
  return 'Row ' + (i + 1) + ': ' + Object.entries(row).map(([k, v]) => k + '=' + v).join(', ');
}).join('\n');

function buildPrompt(regionName, dataText, rowCount) {
  const availability = rowCount === 0
    ? 'IMPORTANT: There is NO data for this region. State clearly that no data was available and do not invent findings.'
    : rowCount === 1
    ? 'IMPORTANT: There is only ONE row of data for this region. Base your analysis solely on that single row. Do not extrapolate trends from a single data point — note the limited data explicitly in your response.'
    : 'Analyse all ' + rowCount + ' rows provided for this region.';

  return 'LANGUAGE RULE: You MUST respond in English only. Do not use any other language under any circumstances, regardless of the language of the input data.\n'
    + 'You are a regional data analyst.\n'
    + 'Your task: ' + task + '\n\n'
    + 'You are responsible for the ' + regionName + ' region ONLY. Do NOT analyse or speculate about other regions.\n'
    + availability + '\n\n'
    + 'Write in clear prose. Be specific and concise. 100-150 words.\n\n'
    + 'Your assigned data (' + regionName + ' region):\n'
    + dataText;
}

const prompt_north = buildPrompt('North', t1, slices.North.length);
const prompt_south = buildPrompt('South', t2, slices.South.length);
const prompt_east  = buildPrompt('East',  t3, slices.East.length);
const prompt_west  = buildPrompt('West',  t4, slices.West.length);

const inputTokenEstimate = Math.ceil(
  (task.length + t1.length + t2.length + t3.length + t4.length) / 4
);

return [{
  json: {
    start_time_ms:        $('Record Start Time').item.json.start_time_ms,
    analysis_task:        task,
    total_rows:           rows.length,
    split_method:         'region_based (North / South / East / West)',
    north_count:          slices.North.length,
    south_count:          slices.South.length,
    east_count:           slices.East.length,
    west_count:           slices.West.length,
    north_raw:            t1,
    south_raw:            t2,
    east_raw:             t3,
    west_raw:             t4,
    all_rows_text:        allRowsText,
    prompt_north:         prompt_north,
    prompt_south:         prompt_south,
    prompt_east:          prompt_east,
    prompt_west:          prompt_west,
    input_token_estimate: inputTokenEstimate
  }
}];

const items = $input.all();
const split = $('Hardcoded Region Split').item.json;

const north = (items[0]?.json?.text || items[0]?.json?.output || '').trim();
const south = (items[1]?.json?.text || items[1]?.json?.output || '').trim();
const east  = (items[2]?.json?.text || items[2]?.json?.output || '').trim();
const west  = (items[3]?.json?.text || items[3]?.json?.output || '').trim();

return [{ json: {
  north_analysis: north,
  south_analysis: south,
  east_analysis:  east,
  west_analysis:  west,
  all_rows_text:  split.all_rows_text
}}];

const split   = $('Hardcoded Region Split').item.json;
const agg     = $('Region Aggregator').item.json;
const startMs = split.start_time_ms;
const task    = split.analysis_task;

const northA = agg.north_analysis || '';
const southA = agg.south_analysis || '';
const eastA  = agg.east_analysis  || '';
const westA  = agg.west_analysis  || '';

const rawOutput   = $input.first().json.output;
const finalAnswer = (rawOutput && typeof rawOutput === 'object' && rawOutput.text)
  ? rawOutput.text : (typeof rawOutput === 'string' ? rawOutput : '');

const endMs    = Date.now();
const latMs    = endMs - startMs;
const inputTok = split.input_token_estimate || 0;
const northTok = Math.ceil(northA.length / 4);
const southTok = Math.ceil(southA.length / 4);
const eastTok  = Math.ceil(eastA.length  / 4);
const westTok  = Math.ceil(westA.length  / 4);
const finalTok = Math.ceil(finalAnswer.length / 4);
const totalOut = northTok + southTok + eastTok + westTok + finalTok;

return [{ json: {
  analysis_task: task,
  final_answer:  finalAnswer,
  metadata: {
    pattern:           'Parallel Sectioning',
    pattern_category:  'Parallel Decomposition Pattern',
    run_timestamp:     new Date().toISOString(),
    model:             'qwen2.5:14b',
    model_provider:    'Ollama (local)',
    latency_ms:        latMs,
    latency_seconds:   parseFloat((latMs / 1000).toFixed(2)),
    llm_calls_actual:  5,
    llm_calls_max:     5,
    token_usage: {
      total_input_tokens:  inputTok,
      total_output_tokens: totalOut,
      total_tokens:        inputTok + totalOut
    },
    status:             'completed',
    termination_reason: 'all_regions_merged_and_synthesised'
  },
  execution_trace: {
    split_strategy: {
      method:       'region_based_partition (hardcoded - zero AI involvement)',
      total_rows:    split.total_rows,
      regions:       ['North', 'South', 'East', 'West'],
      north_count:   split.north_count,
      south_count:   split.south_count,
      east_count:    split.east_count,
      west_count:    split.west_count
    },
    parallel_sections: {
      north: { data_slice: split.north_raw, row_count: split.north_count, output: northA, tokens: northTok },
      south: { data_slice: split.south_raw, row_count: split.south_count, output: southA, tokens: southTok },
      east:  { data_slice: split.east_raw,  row_count: split.east_count,  output: eastA,  tokens: eastTok  },
      west:  { data_slice: split.west_raw,  row_count: split.west_count,  output: westA,  tokens: westTok  }
    },
    synthesis: {
      method:                'stuff (chainSummarization) with ground truth anchor',
      ground_truth_injected:  true,
      output:                finalAnswer,
      tokens:                finalTok
    },
    structural_properties: {
      orchestration_type:       'parallel_fanout_then_merge',
      sections_count:            4,
      sections_run_in_parallel:  true,
      split_node_type:           'code_node_region_based_hardcoded',
      merger_type:               'n8n_merge_node_4_inputs',
      synthesis_node_type:       'chainSummarization_stuff',
      ai_in_orchestration:       false
    }
  }
}}];
